// pipeline.js - Integration layer: normalize, tokenize, analyze
// Relies on normalize.js and tokenizer.js being defined globally.

function normalize(text) {
  return text.normalize("NFKC").toLowerCase().replace(/\s+/g, " ").trim();
}

function tokenize(text) {
  var normalized = normalize(text);
  var tokens = [];
  var current = "";
  var stopwords = { a: true, an: true, the: true, and: true, of: true };

  for (var i = 0; i < normalized.length; i++) {
    var ch = normalized[i];
    // ASCII letters and digits are kept; apostrophe is a separator; everything else is separator.
    if (/[A-Za-z0-9]/.test(ch)) {
      current += ch;
    } else {
      if (current.length > 0) {
        if (!stopwords[current]) {
          tokens.push(current);
        }
        current = "";
      }
    }
  }
  if (current.length > 0) {
    if (!stopwords[current]) {
      tokens.push(current);
    }
  }
  return tokens;
}

function analyze(text) {
  var tokens = tokenize(text);
  var count = tokens.length;
  var unique = [];
  var frequencies = {};

  for (var i = 0; i < tokens.length; i++) {
    var token = tokens[i];
    if (Object.prototype.hasOwnProperty.call(frequencies, token)) {
      frequencies[token]++;
    } else {
      frequencies[token] = 1;
      unique.push(token);
    }
  }

  var uniqueCount = unique.length;
  var summary = count + " tokens; " + uniqueCount + " unique";

  return {
    tokens: tokens,
    count: count,
    unique: unique,
    frequencies: frequencies,
    summary: summary
  };
}
